package com.tasneem.app;
import android.app.*;import android.content.*;import android.os.Build;import androidx.core.app.NotificationCompat;
public class TasneemLockNotification{
 public static void refresh(Context c){android.content.SharedPreferences p=c.getSharedPreferences(TasneemPlugin.PREFS,Context.MODE_PRIVATE);int s=p.getInt("widget_surah",0),a=p.getInt("widget_ayah",0);if(s<=0||a<=0)return;TasneemPlugin.createChannelsFor(c);String text=p.getString("widget_text","");String body="سورة "+s+" — آية "+a+(text.isEmpty()?"":"\n"+text);Intent in=c.getPackageManager().getLaunchIntentForPackage(c.getPackageName());PendingIntent pi=in==null?null:PendingIntent.getActivity(c,9300,in,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);NotificationCompat.Builder n=new NotificationCompat.Builder(c,TasneemPlugin.CHANNEL_LOCK).setSmallIcon(R.drawable.ic_stat_mosque).setContentTitle("تسنيم • آية اليوم").setContentText(body).setStyle(new NotificationCompat.BigTextStyle().bigText(body)).setOnlyAlertOnce(true).setAutoCancel(true).addAction(0,"قرأت الآية",CountReceiver.pending(c,CountReceiver.ACTION_READ,9401));if(pi!=null)n.setContentIntent(pi);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(9301,n.build());}
}
